() => {
  // Try to find auth info in localStorage
  const keys = Object.keys(localStorage);
  const result = {};
  for (const k of keys) {
    try { result[k] = localStorage.getItem(k); } catch(e) {}
  }
  return result;
}

async () => {
  const start = Date.now();
  const timeout = 195000;
  while (Date.now() - start < timeout) {
    const bodyText = document.body.innerText || '';
    const stillThinking = bodyText.includes('AI 正在解析 Schema');
    if (!stillThinking) {
      // count occurrences of assistant header
      const matches = bodyText.split('智能数据分析助手 NL2SQL').length - 1;
      return { done: true, assistantHeaderCount: matches, elapsedMs: Date.now() - start };
    }
    await new Promise(r => setTimeout(r, 3000));
  }
  return { done: false, elapsedMs: Date.now() - start };
}

