() => {
  // Find all elements containing the persona text
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_ELEMENT);
  const results = [];
  let node;
  while (node = walker.nextNode()) {
    const txt = (node.textContent || '').trim();
    if (txt.includes('不良资产客户分析管理专家') && txt.length < 60) {
      const cs = getComputedStyle(node);
      results.push({
        tag: node.tagName,
        className: node.className,
        text: txt,
        color: cs.color,
        backgroundColor: cs.backgroundColor,
        borderColor: cs.borderColor,
        borderRadius: cs.borderRadius
      });
    }
  }
  return results;
}

() => {
  // Find the persona label span
  const spans = Array.from(document.querySelectorAll('span'));
  const label = spans.find(s => (s.textContent || '').trim() === '不良资产客户分析管理专家视角');
  if (!label) return { found: false };
  // Walk up to find the card container: look for an ancestor that contains header + answer body
  let el = label;
  const chain = [];
  while (el && el !== document.body) {
    chain.push({ tag: el.tagName, cls: el.className, h: el.getBoundingClientRect().height });
    el = el.parentElement;
  }
  return { found: true, chain };
}

() => {
  const spans = Array.from(document.querySelectorAll('span'));
  const label = spans.find(s => (s.textContent || '').trim() === '不良资产客户分析管理专家视角');
  if (!label) return { marked: false };
  // card container = ancestor with 'rounded-2xl' and 'bg-slate-900'
  let el = label;
  let card = null;
  while (el && el !== document.body) {
    if (el.className && typeof el.className === 'string' && el.className.includes('rounded-2xl') && el.className.includes('bg-slate-900')) { card = el; break; }
    el = el.parentElement;
  }
  if (!card) return { marked: false, reason: 'no card' };
  card.setAttribute('role', 'region');
  card.setAttribute('aria-label', '最新回答卡片-verify');
  card.scrollIntoView({ block: 'start' });
  return { marked: true, height: card.getBoundingClientRect().height };
}

() => {
  const spans = Array.from(document.querySelectorAll('span'));
  const label = spans.find(s => (s.textContent || '').trim() === '不良资产客户分析管理专家视角');
  if (!label) return { ok: false };
  let card = label;
  while (card && !(card.className && typeof card.className === 'string' && card.className.includes('rounded-2xl'))) card = card.parentElement;
  if (!card) return { ok: false, reason: 'card not found' };
  // cleanup temp a11y attrs
  card.removeAttribute('role');
  card.removeAttribute('aria-label');

  const row = card.parentElement; // message row
  const scroller = row.parentElement; // chat scroll container
  window.__verifyRestore = [];

  // hide sibling messages, keep only this row
  Array.from(scroller.children).forEach(ch => {
    if (ch !== row) {
      window.__verifyRestore.push([ch, ch.style.display]);
      ch.style.display = 'none';
    }
  });

  // expand scroller and ancestors so full card is in normal flow
  const expand = (el) => {
    if (!el || el === document.documentElement) return;
    window.__verifyRestore.push([el, el.getAttribute('style') || '']);
    el.style.height = 'auto';
    el.style.maxHeight = 'none';
    el.style.overflow = 'visible';
    el.style.flex = 'none';
  };
  let el = scroller;
  while (el && el !== document.body) { expand(el); el = el.parentElement; }
  window.__verifyRestore.push([document.body, document.body.getAttribute('style') || '']);
  document.body.style.height = 'auto';
  document.body.style.overflow = 'visible';
  window.__verifyRestore.push([document.documentElement, document.documentElement.getAttribute('style') || '']);
  document.documentElement.style.height = 'auto';
  document.documentElement.style.overflow = 'visible';

  window.scrollTo(0, 0);
  return { ok: true, docHeight: document.documentElement.scrollHeight, docWidth: document.documentElement.scrollWidth };
}

() => {
  const spans = Array.from(document.querySelectorAll('span'));
  const label = spans.find(s => (s.textContent || '').trim() === '不良资产客户分析管理专家视角');
  let card = label;
  while (card && !(card.className && typeof card.className === 'string' && card.className.includes('rounded-2xl'))) card = card.parentElement;
  const r = card.getBoundingClientRect();
  return { cardTop: r.top, cardHeight: r.height, cardWidth: r.width, docHeight: document.documentElement.scrollHeight };
}

() => {
  const restore = window.__verifyRestore || [];
  for (const [el, style] of restore) {
    if (style) el.setAttribute('style', style); else el.removeAttribute('style');
  }
  window.__verifyRestore = null;
  // scroll chat to bottom
  const scroller = document.querySelector('.flex-1.overflow-y-auto');
  if (scroller) scroller.scrollTop = scroller.scrollHeight;
  return { restored: true };
}

